(()=>{'use strict';
const $=id=>document.getElementById(id),toast=text=>{const el=$('studioToast');el.textContent=text;el.hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.hidden=true,3200)};
const panels=[...document.querySelectorAll('aside > .section')],tabs=[...document.querySelectorAll('.studio-tabs button')];
function showPanel(n){tabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===n));tab.tabIndex=i===n?0:-1;panels[i].hidden=i!==n});panels.forEach((panel,i)=>{panel.id='panel-'+i;panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby',tabs[i].id)});}
tabs.forEach((tab,i)=>{tab.setAttribute('aria-controls','panel-'+i);tab.onclick=()=>showPanel(i);tab.onkeydown=e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();showPanel(n);tabs[n].focus()}}});showPanel(0);
const presets={
 cobalt:{name:'Cobalt selvedge',family:'Blue',palette:['#193AC7','#A3BBDF','#F1EAD9','#16254B','#4B78DF','#7C97A8','#CBD4DB','#35568D'],controls:{pattern:'twill',density:52,scale:8,distribution:'stripes',complexity:18,material:'cotton',relief:72,fibre:48,yarnWidth:94,seed:214}},
 moss:{name:'Moss & linen',family:'Green',palette:['#535D38','#A6AA80','#D8D6BE','#EAE4D1','#858C64','#B5BB9A','#39462D','#C3B899'],controls:{pattern:'plain',density:48,scale:12,distribution:'plaid',complexity:15,material:'linen',relief:65,fibre:72,yarnWidth:86,seed:321}},
 ember:{name:'Ember blanket',family:'Red',palette:['#9D372D','#D06B40','#D7B797','#55372F','#EAD4AD','#842B27','#BC865C','#382F2C'],controls:{pattern:'twill',density:46,scale:10,distribution:'plaid',complexity:12,material:'wool',relief:70,fibre:90,yarnWidth:97,seed:618}},
 oat:{name:'Undyed wool',family:'Yellow',palette:['#E9E0CC','#C6B99E','#F1EBD9','#958A74','#D9CFB8','#B4A58E','#DBD5C3','#F6F0E2'],controls:{pattern:'knit',density:36,scale:15,distribution:'horizontal',complexity:5,material:'wool',relief:68,fibre:80,yarnWidth:96,seed:428}},
 electric:{name:'Electric jacquard',family:'Green',palette:['#D4EF2B','#302F43','#AA9ACE','#EEA4C5','#E3E5CD','#627B3B','#4C3ED0','#918A9A'],controls:{pattern:'fairisle',density:40,scale:5,distribution:'patchwork',complexity:48,material:'cotton',relief:72,fibre:55,yarnWidth:93,seed:773}},
 rose:{name:'Rose rib',family:'Red',palette:['#C8878E','#E4C3B8','#866A68','#ECDDD1','#B7948C','#764B56','#D9ADA4','#AC7F87'],controls:{pattern:'rib',density:32,scale:8,distribution:'stripes',complexity:24,material:'wool',relief:78,fibre:90,yarnWidth:100,seed:812}}
};
$('studyPreset').onchange=async()=>{const preset=presets[$('studyPreset').value];if(!preset)return;try{const state=window.loom.getState();await window.loom.setState({...state,...preset,controls:{...state.controls,...preset.controls,count:8,texture:true}});toast(preset.name+' — ready to explore')}catch(e){toast(e.message)}};
// A persistent library stores full projects, including original image data.
const storageKey='chromatic-loom-studies-v2'+(new URLSearchParams(location.search).get('view')==='client'?'-client':'');let studies=[];try{studies=JSON.parse(localStorage.getItem(storageKey)||'[]');if(!Array.isArray(studies))studies=[]}catch(e){studies=[]}
function updateCount(){$('studyCount').textContent=studies.length}updateCount();
function persist(next){localStorage.setItem(storageKey,JSON.stringify(next));studies=next;updateCount()}
function makeThumb(){window.loom.render(true);const canvas=document.createElement('canvas');canvas.width=canvas.height=240;canvas.getContext('2d').drawImage($('art'),0,0,240,240);return canvas.toDataURL('image/jpeg',.82)}
$('saveStudy').onclick=()=>{try{const study={id:Date.now()+'-'+Math.random().toString(36).slice(2,7),state:window.loom.getState(),thumb:makeThumb(),date:new Date().toISOString()};persist([...studies,study]);toast('Study saved to this browser')}catch(e){toast('Browser storage is full or unavailable. Save a project file instead.')}};
function renderLibrary(){const grid=$('studyGrid');grid.replaceChildren();if(!studies.length){const p=document.createElement('p');p.className='empty-library';p.textContent='A place for promising ideas. Save your first study from the studio.';grid.append(p);return}for(const study of [...studies].reverse()){const card=document.createElement('article');card.className='study-card';const img=document.createElement('img');img.src=study.thumb;img.alt=study.state.name||'Material study';const name=document.createElement('p');name.textContent=study.state.name||'Untitled study';const controls=document.createElement('div');controls.className='controls';const open=document.createElement('button');open.textContent='Open study';open.className='primary full';open.onclick=async()=>{try{await window.loom.setState(study.state);$('studyPreset').value='';$('libraryDialog').close();toast('Study opened')}catch(e){toast('Could not open this study: '+e.message)}};const remove=document.createElement('button');remove.textContent='Remove';remove.setAttribute('aria-label','Remove '+name.textContent);remove.onclick=()=>{try{persist(studies.filter(s=>s.id!==study.id));renderLibrary();toast('Study removed')}catch(e){toast('Could not update browser storage')}};controls.append(open,remove);card.append(img,name,controls);grid.append(card)}}
$('openLibrary').onclick=()=>{renderLibrary();$('libraryDialog').showModal()};$('closeLibrary').onclick=()=>$('libraryDialog').close();$('libraryDialog').onclick=e=>{if(e.target===$('libraryDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};
$('exportProject').onclick=()=>{const state=window.loom.getState(),blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(state.name||'chromatic-loom').replace(/[^a-z0-9-]/gi,'-').toLowerCase()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Project file saved with settings and images')};
$('importProject').onclick=()=>$('projectFile').click();$('projectFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>60*1024*1024)throw Error('Project exceeds the 60 MB limit');const state=JSON.parse(await file.text());await window.loom.setState(state);$('studyPreset').value='';toast('Project opened')}catch(err){toast('Could not open project: '+err.message)}finally{e.target.value=''}};
$('quickExport').onclick=()=>$('exportPng').click();$('quickMotion').onclick=()=>{showPanel(4);$('motionPlay').click()};
let inspect=false;function updateZoom(){const frame=document.querySelector('.canvas-frame');frame.style.overflow=inspect?'auto':'hidden';frame.style.alignItems=inspect?'flex-start':'center';frame.style.justifyContent=inspect?'flex-start':'center';for(const id of ['art','motionCanvas']){const c=$(id);c.style.maxWidth=inspect?'none':'';c.style.maxHeight=inspect?'none':'';c.style.width=inspect?'1536px':'';c.style.height=inspect?'1536px':'';c.style.flexShrink=inspect?'0':''}$('viewZoom').textContent=inspect?'Fit to view':'Inspect weave';$('viewZoom').setAttribute('aria-pressed',String(inspect))}$('viewZoom').onclick=()=>{inspect=!inspect;updateZoom()};
// Return to the live still canvas after motion without changing any design settings.
const returnButton=document.createElement('button');returnButton.textContent='Return to still';returnButton.style.marginTop='10px';returnButton.onclick=()=>{window.loomMotion.showStill()};panels[4].append(returnButton);
// Clear the preset selection as soon as the artist departs from it.
for(const el of document.querySelectorAll('aside input:not([type=password]), aside select'))if(el.id!=='studyPreset'&&el.type!=='password')el.addEventListener('input',()=>{$('studyPreset').value=''});
window.loomApplyDefault=async()=>{const shared=window.loomSharedStudy;if(shared){await window.loom.setState(shared.state);for(const [id,value] of Object.entries(shared.values||{})){const element=$(id);if(!element||element.type==='file'||element.type==='password')continue;if(element.type==='checkbox')element.checked=!!value;else if(['INPUT','SELECT','TEXTAREA'].includes(element.tagName))element.value=String(value)}$('studyPreset').value='';window.loom.render();return}await window.loom.setState({...window.loom.getState(),...presets.cobalt,controls:{...window.loom.getState().controls,...presets.cobalt.controls,count:8}});$('studyPreset').value='cobalt'};
})();
